// Differential tests against the FastAPI reference (fixtures/parity.json,
// regenerated by `uv run python convex/parity/generate.py`). Every HTTP
// request the Python suite sends, plus crafted edge cases, must produce the
// same status, Allow/content type and byte-identical body; every parser call
// the Python suite makes, crossed with all eleven fields, must agree.

import { convexTest } from "convex-test";
import { afterEach, beforeEach, describe, expect, test, vi } from "vitest";
import { describe as describeValues } from "../convex/lib/conversation";
import type { ProfileField } from "../convex/lib/models";
import { clarify, groundedCandidates, isSkip, normalizeText, parseReply, parseValue } from "../convex/lib/parsing";
import schema from "../convex/schema";
import fixture from "./fixtures/parity.json";
import { PROVIDER_ENV_PREFIXES, forbidNetwork, mask, modules } from "./helpers";

type Row = unknown[];

function mismatches<T extends Row>(rows: T[], run: (row: T) => unknown, expected: (row: T) => unknown) {
  const failures: { row: T; actual: unknown }[] = [];
  for (const row of rows) {
    const actual = run(row);
    try {
      expect(actual).toEqual(expected(row));
    } catch {
      failures.push({ row, actual });
    }
  }
  return failures.slice(0, 5);
}

describe("parser parity with server/lifetwin/onboarding/parsing.py", () => {
  const parse = fixture.parse as Record<string, Row[]>;

  test("fixture is substantial", () => {
    expect(parse.parse_value.length).toBeGreaterThan(2000);
    expect(parse.grounded_candidates.length).toBeGreaterThan(500);
  });
  test("normalize_text", () => {
    expect(mismatches(parse.normalize_text as [string, string][], ([t]) => normalizeText(t), ([, r]) => r)).toEqual([]);
  });
  test("parse_value", () => {
    const rows = parse.parse_value as [ProfileField, string, object][];
    expect(mismatches(rows, ([f, t]) => parseValue(f, t), ([, , r]) => r)).toEqual([]);
  });
  test("parse_reply", () => {
    const rows = parse.parse_reply as [string, ProfileField, object][];
    expect(mismatches(rows, ([t, f]) => parseReply(t, f), ([, , r]) => r)).toEqual([]);
  });
  test("clarify", () => {
    const rows = parse.clarify as [string, ProfileField, string | null][];
    expect(mismatches(rows, ([t, f]) => clarify(t, f), ([, , r]) => r)).toEqual([]);
  });
  test("is_skip", () => {
    const rows = parse.is_skip as [string, ProfileField, boolean][];
    expect(mismatches(rows, ([t, f]) => isSkip(t, f), ([, , r]) => r)).toEqual([]);
  });
  test("grounded_candidates", () => {
    const rows = parse.grounded_candidates as [string, { candidates: any[] }, ProfileField, object][];
    expect(mismatches(rows, ([t, e, a]) => groundedCandidates(t, e.candidates, a), ([, , , r]) => r)).toEqual([]);
  });
  test("describe (confirmation read-back)", () => {
    const rows = parse.describe as [object, string][];
    expect(mismatches(rows, ([v]) => describeValues(v), ([, r]) => r)).toEqual([]);
  });
});

describe("HTTP parity through the Convex router (convex-test), keyless", () => {
  const saved: Record<string, string | undefined> = {};
  let network: ReturnType<typeof forbidNetwork>;
  beforeEach(() => {
    for (const key of Object.keys(process.env)) {
      if (PROVIDER_ENV_PREFIXES.some((prefix) => key.startsWith(prefix))) {
        saved[key] = process.env[key];
        delete process.env[key];
      }
    }
    network = forbidNetwork();
  });
  afterEach(() => {
    Object.assign(process.env, saved);
    vi.unstubAllGlobals();
  });

  test(`all ${fixture.http.length} recorded and edge-case requests match FastAPI byte for byte`, async () => {
    const t = convexTest(schema, modules);
    const failures: string[] = [];
    for (const item of fixture.http) {
      const headers: Record<string, string> = item.content_type ? { "content-type": item.content_type } : {};
      const binary = (item as { body_b64?: string }).body_b64;
      const body = binary ? Uint8Array.from(atob(binary), (char) => char.charCodeAt(0)) : (item.body ?? undefined);
      const response = await t.fetch(item.path, { method: item.method, headers, body });
      const text = mask(await response.text());
      const problems = [];
      const location = response.headers.get("location")?.replace(/^https?:\/\/[^/]+/, "") ?? null;
      if (location !== ((item as { location?: string | null }).location ?? null)) problems.push(`location ${location}`);
      if (response.status !== item.status) problems.push(`status ${response.status} != ${item.status}`);
      if (response.headers.get("content-type") !== item.response_content_type) problems.push("content-type");
      if (response.headers.get("allow") !== item.allow) problems.push("allow");
      if (text !== item.response) problems.push("body");
      if (response.headers.get("cache-control") !== "no-store") problems.push("cache-control");
      if (!/^[0-9a-f]{32}$/.test(response.headers.get("x-request-id") ?? "")) problems.push("x-request-id");
      if (problems.length) failures.push(`${item.method} ${item.path.slice(0, 60)}: ${problems.join(", ")}`);
    }
    expect(failures).toEqual([]);
    // Keyless mode makes zero network calls, exactly like FastAPI.
    expect(network).not.toHaveBeenCalled();
  });
});
